// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetAuthoring The model the interview uses
	// (GET /admin/authoring)
	GetAuthoring(w http.ResponseWriter, r *http.Request)
	// SetAuthoring Point the interview at a provider
	// (PUT /admin/authoring)
	SetAuthoring(w http.ResponseWriter, r *http.Request)
	// ListBudgets The ceilings configured per scope
	// (GET /admin/budgets)
	ListBudgets(w http.ResponseWriter, r *http.Request)
	// DeleteBudget Remove a scope's ceiling
	// (DELETE /admin/budgets/{scope})
	DeleteBudget(w http.ResponseWriter, r *http.Request, scope string)
	// PutBudget Set a scope's ceiling
	// (PUT /admin/budgets/{scope})
	PutBudget(w http.ResponseWriter, r *http.Request, scope string)
	// EraseContent Erase what a set of runs was about
	// (POST /admin/erasures)
	EraseContent(w http.ResponseWriter, r *http.Request)
	// ListAdminEvents What operators changed about the platform
	// (GET /admin/events)
	ListAdminEvents(w http.ResponseWriter, r *http.Request, params ListAdminEventsParams)
	// ListIdentityProviders How people sign in, and what signing in grants them
	// (GET /admin/identity-providers)
	ListIdentityProviders(w http.ResponseWriter, r *http.Request)
	// DeleteIdentityProvider Remove a way of signing in
	// (DELETE /admin/identity-providers/{id})
	DeleteIdentityProvider(w http.ResponseWriter, r *http.Request, id string)
	// PutIdentityProvider Configure a way of signing in
	// (PUT /admin/identity-providers/{id})
	PutIdentityProvider(w http.ResponseWriter, r *http.Request, id string)
	// ListIntegrations Everything the platform is configured to talk to
	// (GET /admin/integrations)
	ListIntegrations(w http.ResponseWriter, r *http.Request)
	// DeleteMCPServer Remove a tool server
	// (DELETE /admin/integrations/mcp-servers/{name})
	DeleteMCPServer(w http.ResponseWriter, r *http.Request, name string)
	// PutMCPServer Configure a tool server
	// (PUT /admin/integrations/mcp-servers/{name})
	PutMCPServer(w http.ResponseWriter, r *http.Request, name string)
	// DeleteModelProvider Remove a model provider
	// (DELETE /admin/integrations/providers/{name})
	DeleteModelProvider(w http.ResponseWriter, r *http.Request, name string)
	// PutModelProvider Configure a model provider
	// (PUT /admin/integrations/providers/{name})
	PutModelProvider(w http.ResponseWriter, r *http.Request, name string)
	// ListPeople Everybody the installation knows about
	// (GET /admin/people)
	ListPeople(w http.ResponseWriter, r *http.Request)
	// SetGrants What this person may do, granted directly
	// (PUT /admin/people/{principalId}/grants)
	SetGrants(w http.ResponseWriter, r *http.Request, principalId string)
	// ListPrices What this installation pays per model
	// (GET /admin/prices)
	ListPrices(w http.ResponseWriter, r *http.Request)
	// PutPrice Set a model's rate
	// (PUT /admin/prices)
	PutPrice(w http.ResponseWriter, r *http.Request)
	// DeletePrice Withdraw a model's rate
	// (DELETE /admin/prices/{provider}/{model})
	DeletePrice(w http.ResponseWriter, r *http.Request, provider string, model string)
	// GetRetention How long this installation keeps content
	// (GET /admin/retention)
	GetRetention(w http.ResponseWriter, r *http.Request)
	// SetRetention Change how long content is kept
	// (PUT /admin/retention)
	SetRetention(w http.ResponseWriter, r *http.Request)
	// ListScopes The areas that exist
	// (GET /admin/scopes)
	ListScopes(w http.ResponseWriter, r *http.Request)
	// RegisterScope Register an area
	// (POST /admin/scopes)
	RegisterScope(w http.ResponseWriter, r *http.Request)
	// DeleteScope Withdraw an area
	// (DELETE /admin/scopes/{scope})
	DeleteScope(w http.ResponseWriter, r *http.Request, scope string)
	// ListStops What is currently stopped
	// (GET /admin/stops)
	ListStops(w http.ResponseWriter, r *http.Request)
	// SetStop Stop or start a level of the platform
	// (PUT /admin/stops)
	SetStop(w http.ResponseWriter, r *http.Request)
	// ListTools Every tool the platform knows, and what it is classified as
	// (GET /admin/tools)
	ListTools(w http.ResponseWriter, r *http.Request)
	// ClassifyTool Record what a tool does to the world
	// (PUT /admin/tools/{toolId}/classification)
	ClassifyTool(w http.ResponseWriter, r *http.Request, toolId string)
	// ListAgents Published agents
	// (GET /agents)
	ListAgents(w http.ResponseWriter, r *http.Request, params ListAgentsParams)
	// GetEventGraph Who triggers whom
	// (GET /agents/events)
	GetEventGraph(w http.ResponseWriter, r *http.Request)
	// InterviewAgent Turn answers into a draft
	// (POST /agents/interview)
	InterviewAgent(w http.ResponseWriter, r *http.Request)
	// ListTemplates Agents somebody can start from
	// (GET /agents/templates)
	ListTemplates(w http.ResponseWriter, r *http.Request, params ListTemplatesParams)
	// GetAgent One published agent, as it was published
	// (GET /agents/{agentId})
	GetAgent(w http.ResponseWriter, r *http.Request, agentId string, params GetAgentParams)
	// CheckDataFlow Where data from outside reaches an act, before publishing
	// (POST /agents/{agentId}/flow)
	CheckDataFlow(w http.ResponseWriter, r *http.Request, agentId string)
	// SetAgentPaused Start or stop an agent
	// (PUT /agents/{agentId}/paused)
	SetAgentPaused(w http.ResponseWriter, r *http.Request, agentId string)
	// ListRegressions The corrections this agent is held to
	// (GET /agents/{agentId}/regressions)
	ListRegressions(w http.ResponseWriter, r *http.Request, agentId string)
	// RecordRegression Correct a case that came out wrong
	// (POST /agents/{agentId}/regressions)
	RecordRegression(w http.ResponseWriter, r *http.Request, agentId string)
	// DeleteRegression Stop holding the agent to a correction
	// (DELETE /agents/{agentId}/regressions/{caseId})
	DeleteRegression(w http.ResponseWriter, r *http.Request, agentId string, caseId string)
	// StartRun Open a run of this agent
	// (POST /agents/{agentId}/runs)
	StartRun(w http.ResponseWriter, r *http.Request, agentId string, params StartRunParams)
	// StartSimulation Run this agent against occurrences that already happened
	// (POST /agents/{agentId}/simulations)
	StartSimulation(w http.ResponseWriter, r *http.Request, agentId string, params StartSimulationParams)
	// GetSimulation What the agent would have done
	// (GET /agents/{agentId}/simulations/{simulationId})
	GetSimulation(w http.ResponseWriter, r *http.Request, agentId string, simulationId string)
	// SetAgentStage How far this agent is trusted to act alone
	// (PUT /agents/{agentId}/stage)
	SetAgentStage(w http.ResponseWriter, r *http.Request, agentId string)
	// PublishAgent Publish a new version of an agent
	// (PUT /agents/{agentId}/versions)
	PublishAgent(w http.ResponseWriter, r *http.Request, agentId string)
	// ListWebhooks The webhook paths this agent declares
	// (GET /agents/{agentId}/webhooks)
	ListWebhooks(w http.ResponseWriter, r *http.Request, agentId string)
	// RotateWebhookSecret Generate this webhook's secret
	// (POST /agents/{agentId}/webhooks/{path}/secret)
	RotateWebhookSecret(w http.ResponseWriter, r *http.Request, agentId string, path string)
	// ListApprovals The approval inbox
	// (GET /approvals)
	ListApprovals(w http.ResponseWriter, r *http.Request, params ListApprovalsParams)
	// ListAudit What happened, across both records that keep it
	// (GET /audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// ExportLedger A signed range of the ledger
	// (GET /audit/export)
	ExportLedger(w http.ResponseWriter, r *http.Request, params ExportLedgerParams)
	// GetSigningKey The key this installation signs exports with
	// (GET /audit/signing-key)
	GetSigningKey(w http.ResponseWriter, r *http.Request)
	// ListBudgetAlerts Which scopes have crossed a budget threshold
	// (GET /budgets/alerts)
	ListBudgetAlerts(w http.ResponseWriter, r *http.Request, params ListBudgetAlertsParams)
	// GetCostRollup Consumption rolled up over a period
	// (GET /cost)
	GetCostRollup(w http.ResponseWriter, r *http.Request, params GetCostRollupParams)
	// ListDecisions What the Gate has decided, most recent first
	// (GET /decisions)
	ListDecisions(w http.ResponseWriter, r *http.Request, params ListDecisionsParams)
	// Health Liveness probe
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// ListPolicies The rules in force
	// (GET /policies)
	ListPolicies(w http.ResponseWriter, r *http.Request, params ListPoliciesParams)
	// SimulatePolicy What a draft rule would have done
	// (POST /policies/simulate)
	SimulatePolicy(w http.ResponseWriter, r *http.Request, params SimulatePolicyParams)
	// DeletePolicy Remove a policy
	// (DELETE /policies/{code})
	DeletePolicy(w http.ResponseWriter, r *http.Request, code string)
	// PutPolicy Write a policy
	// (PUT /policies/{code})
	PutPolicy(w http.ResponseWriter, r *http.Request, code string)
	// Ready Readiness probe
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// ListRuns List runs
	// (GET /runs)
	ListRuns(w http.ResponseWriter, r *http.Request, params ListRunsParams)
	// GetRunStats Aggregate counts over runs
	// (GET /runs/stats)
	GetRunStats(w http.ResponseWriter, r *http.Request, params GetRunStatsParams)
	// GetThroughput Runs per hour, split by what became of them
	// (GET /runs/throughput)
	GetThroughput(w http.ResponseWriter, r *http.Request, params GetThroughputParams)
	// GetRun Get one run
	// (GET /runs/{runId})
	GetRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// DecideApproval Approve or reject a suspended action
	// (POST /runs/{runId}/approvals)
	DecideApproval(w http.ResponseWriter, r *http.Request, runId RunId)
	// GetCompensation What undoing this run would do
	// (GET /runs/{runId}/compensation)
	GetCompensation(w http.ResponseWriter, r *http.Request, runId RunId)
	// AbandonRun End the run and undo what it left standing
	// (POST /runs/{runId}/compensation)
	AbandonRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// ReplayRun Would these decisions be made the same way again?
	// (GET /runs/{runId}/replay)
	ReplayRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// ResumeRun Return a parked run to the queue
	// (POST /runs/{runId}/resume)
	ResumeRun(w http.ResponseWriter, r *http.Request, runId RunId)
	// ListRunSteps Read the run's ledger trail
	// (GET /runs/{runId}/steps)
	ListRunSteps(w http.ResponseWriter, r *http.Request, runId RunId, params ListRunStepsParams)
	// GetStepContent Read the content a step references
	// (GET /runs/{runId}/steps/{seq}/content)
	GetStepContent(w http.ResponseWriter, r *http.Request, runId RunId, seq int64)
	// VerifyRun Verify the run's hash chain
	// (POST /runs/{runId}/verify)
	VerifyRun(w http.ResponseWriter, r *http.Request, runId RunId)
}

